def transform(grid):
    R, C = len(grid), len(grid[0])
    hsep = None
    for i in range(R):
        if all(v == grid[i][0] and v != 0 for v in grid[i]):
            hsep = i
            break
    vsep = None
    if hsep is None:
        for j in range(C):
            if all(grid[i][j] == grid[0][j] and grid[0][j] != 0 for i in range(R)):
                vsep = j
                break
    out = []
    if hsep is not None:
        top = grid[:hsep]
        bottom = grid[hsep+1:]
        for r in range(len(top)):
            row = []
            for c in range(C):
                b = bottom[r][c] if r < len(bottom) else 0
                row.append(2 if (top[r][c] != 0 and b != 0) else 0)
            out.append(row)
    else:
        left = [row[:vsep] for row in grid]
        right = [row[vsep+1:] for row in grid]
        for r in range(R):
            row = []
            for c in range(len(left[r])):
                b = right[r][c] if c < len(right[r]) else 0
                row.append(2 if (left[r][c] != 0 and b != 0) else 0)
            out.append(row)
    return out
